"use client";

import styled from "styled-components";

interface RatingStarInputProps {
  value: number;
  onChange: (value: number) => void;
  label?: string;
}

export function RatingStarInput({ value, onChange, label = "별점" }: RatingStarInputProps) {
  return (
    <StarGroup role="radiogroup" aria-label={label}>
      {Array.from({ length: 5 }, (_, index) => {
        const score = index + 1;
        const selected = score <= value;

        return (
          <StarButton
            key={score}
            type="button"
            role="radio"
            aria-label={`${score}점`}
            aria-checked={value === score}
            $selected={selected}
            onClick={() => onChange(score)}
            onKeyDown={(event) => {
              if (event.key === "ArrowRight" || event.key === "ArrowUp") {
                event.preventDefault();
                onChange(Math.min(5, score + 1));
              }
              if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
                event.preventDefault();
                onChange(Math.max(1, score - 1));
              }
              if (event.key === "Home") {
                event.preventDefault();
                onChange(1);
              }
              if (event.key === "End") {
                event.preventDefault();
                onChange(5);
              }
            }}
          >
            <svg viewBox="0 0 32 32" aria-hidden="true">
              <path d={selected ? STAR_FILLED_PATH : STAR_OUTLINE_PATH} fillRule="evenodd" clipRule="evenodd" />
            </svg>
          </StarButton>
        );
      })}
    </StarGroup>
  );
}

